import {
  WHISPER_MAX_WAV_BYTES,
  WHISPER_SAMPLE_RATE,
  WHISPER_WAV_HEADER_BYTES,
} from '@nanachi/shared';

/** Accepts the canonical PCM WAV generated by the chat recorder. */
export function isWhisperWav(bytes: unknown): bytes is Buffer {
  if (!Buffer.isBuffer(bytes) || bytes.length <= WHISPER_WAV_HEADER_BYTES || bytes.length > WHISPER_MAX_WAV_BYTES) {
    return false;
  }
  return bytes.length % 2 === 0 &&
    bytes.toString('ascii', 0, 4) === 'RIFF' &&
    bytes.readUInt32LE(4) === bytes.length - 8 &&
    bytes.toString('ascii', 8, 16) === 'WAVEfmt ' &&
    bytes.readUInt32LE(16) === 16 &&
    bytes.readUInt16LE(20) === 1 &&
    bytes.readUInt16LE(22) === 1 &&
    bytes.readUInt32LE(24) === WHISPER_SAMPLE_RATE &&
    bytes.readUInt32LE(28) === WHISPER_SAMPLE_RATE * 2 &&
    bytes.readUInt16LE(32) === 2 &&
    bytes.readUInt16LE(34) === 16 &&
    bytes.toString('ascii', 36, 40) === 'data' &&
    bytes.readUInt32LE(40) === bytes.length - WHISPER_WAV_HEADER_BYTES;
}

export function hasWhisperSamples(bytes: Buffer): boolean {
  return bytes.subarray(WHISPER_WAV_HEADER_BYTES).some((byte) => byte !== 0);
}
